      width: 100%;
      padding: 14px 52px 14px 18px;
      font-size: 1rem;
      font-family: inherit;
      border: 1.5px solid #D0D0D0;
      border-radius: 8px;
      background: #FFFFFF;
      color: #121212;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
