    .search-input::placeholder {
      color: #999999;
    }

    .search-input:focus {
      border-color: #EB0028;
      box-shadow: 0 0 0 3px rgba(235, 0, 40, 0.08);
    }

    .search-button {
      position: absolute;
      right: 6px;
      top: 50%;
      transform: translateY(-50%);
