      outline-offset: 2px;
      border-radius: 2px;
    }

    /* Cookie Banner */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: #1A1A1A;
      color: #D4D4D4;
      padding: 20px 24px;
      z-index: 1000;
      transform: translateY(0);
      transition: transform 0.35s ease;
    }

    .cookie-banner.hidden {
      transform: translateY(100%);
      pointer-events: none;
    }

    .cookie-inner {
      max-width: 960px;
      margin: 0 auto;
      display: flex;
      align-items: flex-start;
      gap: 24px;
    }

    .cookie-text {
      flex: 1;
      font-size: 0.85rem;
      line-height: 1.6;
      color: #C0C0C0;
    }

    .cookie-text a {
      color: #FFFFFF;
      text-decoration: underline;
      text-underline-offset: 2px;
    }

    .cookie-text a:hover {
      color: #EB0028;
    }

    .cookie-actions {
      display: flex;
      gap: 12px;
      flex-shrink: 0;
      align-items: center;
    }

    .btn-manage {
      padding: 10px 20px;
      font-size: 0.85rem;
      font-family: inherit;
      font-weight: 500;
      border: 1.5px solid #555555;
      border-radius: 6px;
      background: transparent;
      color: #FFFFFF;
      cursor: pointer;
      white-space: nowrap;
      transition: border-color 0.2s ease, background-color 0.2s ease;
