    .btn-manage:hover {
      border-color: #FFFFFF;
      background: rgba(255, 255, 255, 0.06);
    }

    .btn-manage:focus-visible {
      outline: 2px solid #FFFFFF;
      outline-offset: 2px;
    }

    /* Cookie Preferences Modal */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.5);
