    .toggle-slider {
      position: absolute;
      inset: 0;
      background: #D0D0D0;
      border-radius: 24px;
      cursor: pointer;
      transition: background 0.2s ease;
    }

    .toggle-slider::after {
      content: '';
      position: absolute;
      width: 18px;
      height: 18px;
      background: #FFFFFF;
      border-radius: 50%;
      top: 3px;
      left: 3px;
      transition: transform 0.2s ease;
    }

    .toggle-switch input:checked + .toggle-slider {
      background: #EB0028;
    }

    .toggle-switch input:checked + .toggle-slider::after {
      transform: translateX(20px);
    }

    .toggle-switch input:disabled + .toggle-slider {
      opacity: 0.5;
