    <!-- Error Message -->
    <div class="error-message">
      <h1>Sorry, we can't find that.</h1>
      <p>Perhaps we can help you find the content you're looking for:</p>
    </div>

    <!-- Search -->
    <div class="search-container">
      <form class="search-form" role="search" action="#" id="searchForm">
        <label for="searchInput" class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);">Search IdeaForum</label>
