      <div class="next-steps-links">
        <a href="/">Go to the homepage</a>
        <a href="/help">Visit our Help Desk</a>
      </div>
    </div>
  </main>

  <!-- Cookie Consent Banner -->
  <div class="cookie-banner" id="cookieBanner" role="region" aria-label="Cookie consent">
    <div class="cookie-inner">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link: <a href="/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <div class="cookie-actions">
        <button class="btn-manage" id="managePrefsBtn">Manage Preferences</button>
      </div>
    </div>
  </div>

  <!-- Cookie Preferences Modal -->
  <div class="modal-overlay" id="prefsModal" role="dialog" aria-modal="true" aria-labelledby="prefsTitle">
    <div class="modal">
      <div class="modal-header">
        <h3 id="prefsTitle">Cookie Preferences</h3>
        <button class="modal-close" id="modalCloseBtn" aria-label="Close preferences">
          <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <line x1="6" y1="6" x2="18" y2="18"/>
            <line x1="18" y1="6" x2="6" y2="18"/>
