      </div>

      <div class="preference-group">
        <div class="preference-row">
          <span class="preference-label">Essential</span>
          <label class="toggle-switch">
            <input type="checkbox" checked disabled>
            <span class="toggle-slider"></span>
          </label>
        </div>
        <p class="preference-desc">Required for the site to function. These cannot be disabled.</p>
      </div>

      <div class="preference-group">
        <div class="preference-row">
          <span class="preference-label">Analytics</span>
          <label class="toggle-switch">
            <input type="checkbox" id="toggleAnalytics">
            <span class="toggle-slider"></span>
          </label>
        </div>
        <p class="preference-desc">Help us understand how visitors interact with our site to improve the experience.</p>
      </div>

      <div class="preference-group">
        <div class="preference-row">
          <span class="preference-label">Personalization</span>
          <label class="toggle-switch">
            <input type="checkbox" id="togglePersonalization">
            <span class="toggle-slider"></span>
          </label>
        </div>
        <p class="preference-desc">Allow us to tailor content and recommendations based on your interests.</p>
      </div>

      <div class="preference-group">
        <div class="preference-row">
          <span class="preference-label">Advertising</span>
          <label class="toggle-switch">
            <input type="checkbox" id="toggleAdvertising">
            <span class="toggle-slider"></span>
          </label>
        </div>
        <p class="preference-desc">Enable targeted advertising based on your browsing activity.</p>
      </div>

      <div class="modal-footer">
        <button class="btn-cancel" id="modalCancelBtn">Cancel</button>
        <button class="btn-save" id="modalSaveBtn">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    (function () {
      var searchForm = document.getElementById('searchForm');
      var searchInput = document.getElementById('searchInput');
      var cookieBanner = document.getElementById('cookieBanner');
      var managePrefsBtn = document.getElementById('managePrefsBtn');
      var prefsModal = document.getElementById('prefsModal');
      var modalCloseBtn = document.getElementById('modalCloseBtn');
      var modalCancelBtn = document.getElementById('modalCancelBtn');
      var modalSaveBtn = document.getElementById('modalSaveBtn');

      searchForm.addEventListener('submit', function (e) {
        e.preventDefault();
        var query = searchInput.value.trim();
        if (query) {
          window.location.href = '/search?q=' + encodeURIComponent(query);
        }
      });

      function openModal() {
        prefsModal.classList.add('active');
        document.body.style.overflow = 'hidden';
        modalCloseBtn.focus();
      }

      function closeModal() {
        prefsModal.classList.remove('active');
        document.body.style.overflow = '';
        managePrefsBtn.focus();
      }

      managePrefsBtn.addEventListener('click', openModal);
      modalCloseBtn.addEventListener('click', closeModal);
      modalCancelBtn.addEventListener('click', closeModal);

      modalSaveBtn.addEventListener('click', function () {
        cookieBanner.classList.add('hidden');
        closeModal();
      });

      prefsModal.addEventListener('click', function (e) {
        if (e.target === prefsModal) closeModal();
      });

      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && prefsModal.classList.contains('active')) {
          closeModal();
        }
      });
    })();
  </script>
